window.docContents[236].resolve({"/#Quadratic-Number-Fields-Blueprint":{"contents":"This is a Verso blueprint for the QuadraticNumberFields project. It presents\nhow the formalization organizes abstract quadratic fields, the standard model\n, integer-ring classifications, discriminants, ideals,\nunits, and class-group checks, culminating in the Baker--Heegner--Stark\nchapter: the nine Heegner numbers are proved to have class number one, and the\ndeep converse is recorded as the remaining long-term goal.\n\nThe blueprint is intentionally a nested Lake package: it imports the project for\ndeclaration links, but it does not add Verso dependencies to the main Lean\nlibrary.\n\nReturn to numbertheory.cc.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Quadratic Number Fields Blueprint","id":"/#Quadratic-Number-Fields-Blueprint"}});